class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[alt_sum] = set of achievable products (<= limit) for that alternating sum
        # We use a dictionary mapping alternating sum -> set of products
        # Since nums[i] <= 12 and limit <= 5000, products are bounded.
        # Alternating sum range: each element contributes +/- nums[i], max |sum| <= 150*12 = 1800.
        # But k can be up to 1e5, so we offset or just use dict keys.

        # dp: dict alt_sum -> set of products
        dp = {0: {1}}  # empty subsequence: alt sum 0, product 1 (we'll exclude empty at end)

        for num in nums:
            new_dp = {s: set(prods) for s, prods in dp.items()}
            for s, prods in dp.items():
                # Include num at even position (add to sum)
                ns = s + num
                for p in prods:
                    np = p * num
                    if np <= limit:
                        if ns not in new_dp:
                            new_dp[ns] = set()
                        new_dp[ns].add(np)
                # Include num at odd position (subtract from sum)
                ns = s - num
                for p in prods:
                    np = p * num
                    if np <= limit:
                        if ns not in new_dp:
                            new_dp[ns] = set()
                        new_dp[ns].add(np)
            dp = new_dp

        # Wait: the parity of position depends on how many elements already chosen.
        # The above approach is wrong because whether num is at even or odd index
        # depends on the current length of the subsequence, not a free choice.
        # We need to track parity (length mod 2) as state.

        # Redo with parity state:
        # dp[(alt_sum, parity)] = set of products
        # parity = number of selected elements mod 2 (next element's index parity)
        dp = {(0, 0): {1}}

        for num in nums:
            new_dp = {key: set(prods) for key, prods in dp.items()}
            for (s, parity), prods in dp.items():
                if parity == 0:
                    ns = s + num
                else:
                    ns = s - num
                nparity = 1 - parity
                for p in prods:
                    np = p * num
                    if np <= limit:
                        key = (ns, nparity)
                        if key not in new_dp:
                            new_dp[key] = set()
                        new_dp[key].add(np)
            dp = new_dp

        best = -1
        for parity in (0, 1):
            key = (k, parity)
            if key in dp:
                for p in dp[key]:
                    # Exclude empty subsequence: empty has product 1, alt sum 0, parity 0
                    if p == 1 and k == 0 and parity == 0:
                        # Could be empty subsequence; but product 1 could also come from non-empty
                        # e.g., selecting 1s. We need to be careful.
                        pass
                    if p > best:
                        best = p

        # Handle empty subsequence issue: if best == 1 and k == 0, the product 1 might
        # only be achievable by the empty subsequence. We need to track whether a non-empty
        # subsequence achieves it. Let's redo with tracking count or a flag.

        # Simpler: track dp[(alt_sum, parity)] = set of products, but initialize empty
        # and only add when selecting. Use a separate approach: don't seed with empty,
        # but handle first element specially. Actually seeding with empty is fine as long
        # as we exclude the empty result. Product 1 from empty only matters if no non-empty
        # subsequence gives product 1 with alt sum k. Since nums[i] >= 0, product 1 non-empty
        # requires all selected elements to be 1 (or product 1 with... only 1s since nums[i]>=0
        # and integers; 0 gives product 0). So if k==0 and best==1, we need to verify a
        # non-empty subsequence exists. 

        # To be safe, track with a "started" flag: dp[(alt_sum, parity, started)].
        dp = {}
        dp[(0, 0, False)] = {1}

        for num in nums:
            new_dp = {key: set(prods) for key, prods in dp.items()}
            for (s, parity, started), prods in dp.items():
                if parity == 0:
                    ns = s + num
                else:
                    ns = s - num
                nparity = 1 - parity
                for p in prods:
                    np = p * num
                    if np <= limit:
                        key = (ns, nparity, True)
                        if key not in new_dp:
                            new_dp[key] = set()
                        new_dp[key].add(np)
            dp = new_dp

        best = -1
        for parity in (0, 1):
            key = (k, parity, True)
            if key in dp:
                for p in dp[key]:
                    if p > best:
                        best = p

        return best

