    input = sys.stdin.readline
    N = int(input())
    S = input().strip()
    T = input().strip()

    # Build mapping from each character in S to the corresponding character in T
    mapping = {}
    for s_char, t_char in zip(S, T):
        if s_char in mapping:
            if mapping[s_char] != t_char:
                print(-1)
                return
        else:
            mapping[s_char] = t_char

    # Check if any target character is not present in S
    s_chars = set(S)
    t_chars = set(T)
    if not t_chars.issubset(s_chars):
        print(-1)
        return

    # Build graph of required transformations (excluding identity mappings)
    graph = {}
    for a, b in mapping.items():
        if a != b:
            graph[a] = b

    visited = set()
    total_ops = 0

    for node in graph:
        if node in visited:
            continue
        # Traverse the chain starting from node
        curr = node
        path = []
        while curr in graph and curr not in visited:
            visited.add(curr)
            path.append(curr)
            curr = graph[curr]

        # Check if we found a cycle
        if curr in path:
            cycle_start = path.index(curr)
            cycle_length = len(path) - cycle_start
            # A cycle of length L requires L+1 operations
            total_ops += cycle_length + 1
            # The non-cycle part (if any) requires one operation per edge
            total_ops += cycle_start
        else:
            # No cycle, just a chain: one operation per node in path
            total_ops += len(path)

    print(total_ops)

