class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count_upto(n: int) -> int:
            if n <= 0:
                return 0
            digits = list(map(int, str(n)))
            length = len(digits)

            @lru_cache(maxsize=None)
            def dp(pos: int, tight: bool, started: bool, digit_sum: int, digit_prod: int) -> int:
                if pos == length:
                    if not started:
                        return 0
                    if digit_sum == 0:
                        return 0
                    return 1 if digit_prod % digit_sum == 0 else 0

                limit = digits[pos] if tight else 9
                total = 0
                for d in range(limit + 1):
                    new_tight = tight and (d == limit)
                    if not started and d == 0:
                        total += dp(pos + 1, new_tight, False, 0, 1)
                    else:
                        new_started = True
                        new_sum = digit_sum + d
                        new_prod = digit_prod * d if started else d
                        total += dp(pos + 1, new_tight, True, new_sum, new_prod)
                return total

            return dp(0, True, False, 0, 1)

        return count_upto(r) - count_upto(l - 1)

class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        L = n + m - 1
        word = ['a'] * L
        fixed = [False] * L

        # Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if fixed[pos] and word[pos] != str2[j]:
                        return ""
                    word[pos] = str2[j]
                    fixed[pos] = True

        # Check all 'F' constraints
        for i in range(n):
            if str1[i] == 'F':
                # Check if substring matches str2
                match = True
                for j in range(m):
                    if word[i + j] != str2[j]:
                        match = False
                        break

                if match:
                    # Need to break this match
                    # Find rightmost non-fixed position in [i, i+m-1]
                    changed = False
                    for pos in range(i + m - 1, i - 1, -1):
                        if not fixed[pos]:
                            word[pos] = 'b'
                            changed = True
                            break

                    if not changed:
                        # All positions are fixed, try to find a position we can change
                        # by checking if changing it breaks other constraints minimally
                        # Actually, if all are fixed and it matches, we cannot satisfy this F
                        return ""

        # Verify all constraints are satisfied
        for i in range(n):
            substring = ''.join(word[i:i+m])
            if str1[i] == 'T' and substring != str2:
                return ""
            if str1[i] == 'F' and substring == str2:
                return ""

        return ''.join(word)

