def main():
    MOD = 998244353
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    s = data[1].strip()
    a = [1 if ch == '1' else 0 for ch in s]
    total_ones = sum(a)
    M = N + total_ones

    # Precompute factorials and inverse factorials up to M
    max_n = M
    fact = [1] * (max_n + 1)
    for i in range(1, max_n + 1):
        fact[i] = fact[i-1] * i % MOD
    inv_fact = [1] * (max_n + 1)
    inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
    for i in range(max_n, 0, -1):
        inv_fact[i-1] = inv_fact[i] * i % MOD

    def comb(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % MOD * inv_fact[n-k] % MOD

    # Compute S1 = sum_{k=0}^{N} (-1)^k C(N,k) C(M-2k, N)
    S1 = 0
    for k in range(0, N+1):
        term = comb(N, k) * comb(M - 2*k, N) % MOD
        if k % 2 == 0:
            S1 = (S1 + term) % MOD
        else:
            S1 = (S1 - term) % MOD

    # Compute S2 = sum_{k=0}^{N} (-1)^k C(N,k) C(M-2k-1, N-1)
    S2 = 0
    for k in range(0, N+1):
        term = comb(N, k) * comb(M - 2*k - 1, N-1) % MOD
        if k % 2 == 0:
            S2 = (S2 + term) % MOD
        else:
            S2 = (S2 - term) % MOD

    # Compute T1 = sum_{k=0}^{N-1} (-1)^k C(N-1,k) C(M-2k-1, N-1)
    T1 = 0
    for k in range(0, N):
        term = comb(N-1, k) * comb(M - 2*k - 1, N-1) % MOD
        if k % 2 == 0:
            T1 = (T1 + term) % MOD
        else:
            T1 = (T1 - term) % MOD

    # Compute T2 = sum_{k=0}^{N-1} (-1)^k C(N-1,k) C(M-2k-2, N-2)
    T2 = 0
    for k in range(0, N):
        term = comb(N-1, k) * comb(M - 2*k - 2, N-2) % MOD
        if k % 2 == 0:
            T2 = (T2 + term) % MOD
        else:
            T2 = (T2 - term) % MOD

    # Compute the final answer
    part1 = (S1 - S2) % MOD
    part2 = (T1 - T2) % MOD
    ans = (part1 + total_ones * part2) % MOD
    print(ans)

