class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Directions: 0: down-right, 1: down-left, 2: up-left, 3: up-right
        # Clockwise turn: (i + 1) % 4
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]

        # memo[i][j][d][t] stores the max length starting at (i, j) 
        # moving in direction d, where t=1 means a turn is still allowed.
        memo = [[[[-1] * 2 for _ in range(4)] for _ in range(m)] for _ in range(n)]

        def get_next_val(curr_val):
            if curr_val == 1:
                return 2
            return 2 if curr_val == 0 else 0

        def dfs(r, c, d, can_turn):
            if memo[r][c][d][can_turn] != -1:
                return memo[r][c][d][can_turn]

            dr, dc = dirs[d]
            nr, nc = r + dr, c + dc
            res = 1

            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == get_next_val(grid[r][c]):
                # Option 1: Continue straight
                res = max(res, 1 + dfs(nr, nc, d, can_turn))

                # Option 2: Take a clockwise 90-degree turn if allowed
                if can_turn:
                    nd = (d + 1) % 4
                    res = max(res, 1 + dfs(nr, nc, nd, 0))

            memo[r][c][d][can_turn] = res
            return res

        max_len = 0
        for i in range(n):
            for j in range(m):
                if grid[i][j] == 1:
                    for d in range(4):
                        max_len = max(max_len, dfs(i, j, d, 1))

        return max_len

