class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        # For each possible non-zero last digit d, maintain prefix sums mod d
        # counts[d][r] = number of prefix sums (for mod d) equal to r
        counts = [None] + [[0] * d for d in range(1, 10)]
        # current prefix value mod d for each d
        pref = [0] * 10
        # empty prefix
        for d in range(1, 10):
            counts[d][0] = 1
        for ch in s:
            x = ord(ch) - 48
            for d in range(1, 10):
                pref[d] = (pref[d] * 10 + x) % d
            if x != 0:
                # substrings ending here with last digit x:
                # need prefix_before ≡ current_prefix (mod x)
                ans += counts[x][pref[x]]
            for d in range(1, 10):
                counts[d][pref[d]] += 1
        return ans

