def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0]); P = int(data[1])
    n = N
    half = n // 2
    maxM = n * (n - 1) // 2

    # Precompute binomial coefficients C(a,b) mod P for 0<=b<=a<=maxM
    C = [[0] * (maxM + 1) for _ in range(maxM + 1)]
    for i in range(maxM + 1):
        C[i][0] = 1 % P
        for j in range(1, i + 1):
            C[i][j] = (C[i-1][j-1] + C[i-1][j]) % P

    # Precompute powers of 2 modulo P up to maxM
    pow2 = [1] * (maxM + 1)
    for i in range(1, maxM + 1):
        pow2[i] = (pow2[i-1] * 2) % P

    # total connected labeled graphs on k vertices by edges
    total_conn = [[0] * (maxM + 1) for _ in range(n + 1)]
    for k in range(1, n + 1):
        maxe = k * (k - 1) // 2
        for e in range(maxe + 1):
            total_conn[k][e] = C[maxe][e]
    for k in range(2, n + 1):
        maxe = k * (k - 1) // 2
        for e in range(maxe + 1):
            s = 0
            for j in range(1, k):
                maxj = j * (j - 1) // 2
                ckj = C[k-1][j-1]
                for f in range(maxj + 1):
                    if total_conn[j][f]:
                        s = (s + ckj * total_conn[j][f] % P * C[(k-j)*(k-j-1)//2][e-f]) % P
            total_conn[k][e] = (total_conn[k][e] - s) % P

    # B[k][e]: connected bipartite graphs on k labeled vertices with a fixed bipartition (sizes a,b)
    B = [[0] * (maxM + 1) for _ in range(n + 1)]
    for a in range(1, n):
        b = n - a
        maxe = a * b
        for e in range(maxe + 1):
            B[a][e] = C[maxe][e]
        for e in range(maxe + 1):
            s = 0
            for i in range(1, a + 1):
                for j in range(0, b + 1):
                    if i == a and j == b:
                        continue
                    if i + j == 0:
                        continue
                    maxij = i * j
                    ways_split = C[a-1][i-1] * C[b][j] % P
                    for f in range(maxij + 1):
                        if B[i][f]:
                            s = (s + ways_split * B[i][f] % P * C[(a-i)*(b-j)][e-f]) % P
            B[a][e] = (B[a][e] - s) % P

    # A[k][e]: connected graphs on k labeled vertices where vertex 1 has even distance count = odd count
    A = [[0] * (maxM + 1) for _ in range(n + 1)]
    for e in range(maxM + 1):
        A[1][e] = 0
    for k in range(2, n + 1):
        maxe = k * (k - 1) // 2
        if k % 2 == 0:
            h = k // 2
            for e in range(maxe + 1):
                A[k][e] = B[h][e] * pow2[h * (h - 1)] % P
        else:
            for e in range(maxe + 1):
                A[k][e] = 0

    # Rooted connected graphs with balance condition (component containing vertex 1)
    root = [[0] * (maxM + 1) for _ in range(n + 1)]
    for k in range(1, n + 1):
        maxe = k * (k - 1) // 2
        for e in range(maxe + 1):
            if k % 2 == 0:
                root[k][e] = A[k][e]
            else:
                s = 0
                for j in range(2, k + 1, 2):  # even j
                    maxj = j * (j - 1) // 2
                    c = C[k-1][j-1]
                    for f in range(maxj + 1):
                        if A[j][f]:
                            s = (s + c * A[j][f] % P * total_conn[k-j][e-f]) % P
                root[k][e] = s

    # Final answers for N vertices
    ans = [0] * (maxM + 1)
    for M in range(n - 1, maxM + 1):
        total = 0
        for k in range(2, n + 1, 2):  # even k
            maxk = k * (k - 1) // 2
            c = C[n-1][k-1]
            for e in range(maxk + 1):
                if root[k][e]:
                    total = (total + c * root[k][e] % P * total_conn[n-k][M-e]) % P
        ans[M] = total

    out = ' '.join(str(ans[M] % P) for M in range(n - 1, maxM + 1))
    sys.stdout.write(out)

