def main():
    MOD = 998244353
    input = sys.stdin.readline

    H, W = map(int, input().split())
    A = [list(map(int, input().split())) for _ in range(H)]
    Q, sh, sw = map(int, input().split())
    sh -= 1
    sw -= 1

    # dp[i][j] = sum of products of paths from (0,0) to (i,j)
    dp = [[0] * W for _ in range(H)]
    dp[0][0] = A[0][0] % MOD
    for j in range(1, W):
        dp[0][j] = dp[0][j-1] * A[0][j] % MOD
    for i in range(1, H):
        dp[i][0] = dp[i-1][0] * A[i][0] % MOD
    for i in range(1, H):
        for j in range(1, W):
            dp[i][j] = (dp[i-1][j] + dp[i][j-1]) * A[i][j] % MOD

    # g[i][j] = sum of products of paths from (i,j) to (H-1,W-1)
    g = [[0] * W for _ in range(H)]
    g[H-1][W-1] = A[H-1][W-1] % MOD
    for j in range(W-2, -1, -1):
        g[H-1][j] = g[H-1][j+1] * A[H-1][j] % MOD
    for i in range(H-2, -1, -1):
        g[i][W-1] = g[i+1][W-1] * A[i][W-1] % MOD
    for i in range(H-2, -1, -1):
        for j in range(W-2, -1, -1):
            g[i][j] = (g[i+1][j] + g[i][j+1]) * A[i][j] % MOD

    # invA[i][j] = modular inverse of A[i][j], or 0 if A[i][j] == 0
    invA = [[0] * W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if A[i][j] != 0:
                invA[i][j] = pow(A[i][j], MOD-2, MOD)

    out = []
    cur_h, cur_w = sh, sw
    for _ in range(Q):
        d, a = input().split()
        a = int(a)
        if d == 'L':
            cur_w -= 1
        elif d == 'R':
            cur_w += 1
        elif d == 'U':
            cur_h -= 1
        else:  # 'D'
            cur_h += 1
        i, j = cur_h, cur_w
        old_a = A[i][j]
        A[i][j] = a
        if a != 0:
            invA[i][j] = pow(a, MOD-2, MOD)
        else:
            invA[i][j] = 0

        # Update dp for cell (i,j)
        if i == 0 and j == 0:
            new_dp = a % MOD
        elif i == 0:
            new_dp = dp[0][j-1] * a % MOD
        elif j == 0:
            new_dp = dp[i-1][0] * a % MOD
        else:
            new_dp = (dp[i-1][j] + dp[i][j-1]) * a % MOD
        delta_dp = (new_dp - dp[i][j]) % MOD
        dp[i][j] = new_dp

        # Update g for cell (i,j)
        if i == H-1 and j == W-1:
            new_g = a % MOD
        elif i == H-1:
            new_g = g[H-1][j+1] * a % MOD
        elif j == W-1:
            new_g = g[i+1][W-1] * a % MOD
        else:
            new_g = (g[i+1][j] + g[i][j+1]) * a % MOD
        delta_g = (new_g - g[i][j]) % MOD
        g[i][j] = new_g

        # Propagate dp changes to the right and down
        # Right propagation in row i
        for jj in range(j+1, W):
            if i == 0:
                new_dp = dp[0][jj-1] * A[0][jj] % MOD
            else:
                new_dp = (dp[i-1][jj] + dp[i][jj-1]) * A[i][jj] % MOD
            if new_dp == dp[i][jj]:
                break
            dp[i][jj] = new_dp
        # Down propagation in column j
        for ii in range(i+1, H):
            if j == 0:
                new_dp = dp[ii-1][0] * A[ii][0] % MOD
            else:
                new_dp = (dp[ii-1][j] + dp[ii][j-1]) * A[ii][j] % MOD
            if new_dp == dp[ii][j]:
                break
            dp[ii][j] = new_dp
        # Propagate to the subgrid (i+1..H-1, j+1..W-1)
        # We process cells in order of increasing i+j, but only those affected.
        # Use a queue/stack for affected cells.
        from collections import deque
        queue = deque()
        if i+1 < H and j+1 < W:
            queue.append((i+1, j+1))
        visited = set()
        while queue:
            x, y = queue.popleft()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            new_dp = (dp[x-1][y] + dp[x][y-1]) * A[x][y] % MOD
            if new_dp != dp[x][y]:
                dp[x][y] = new_dp
                if x+1 < H:
                    queue.append((x+1, y))
                if y+1 < W:
                    queue.append((x, y+1))

        # Propagate g changes to the left and up
        # Left propagation in row i
        for jj in range(j-1, -1, -1):
            if i == H-1:
                new_g = g[H-1][jj+1] * A[H-1][jj] % MOD
            else:
                new_g = (g[i+1][jj] + g[i][jj+1]) * A[i][jj] % MOD
            if new_g == g[i][jj]:
                break
            g[i][jj] = new_g
        # Up propagation in column j
        for ii in range(i-1, -1, -1):
            if j == W-1:
                new_g = g[ii+1][W-1] * A[ii][W-1] % MOD
            else:
                new_g = (g[ii+1][j] + g[ii][j+1]) * A[ii][j] % MOD
            if new_g == g[ii][j]:
                break
            g[ii][j] = new_g
        # Propagate to the subgrid (0..i-1, 0..j-1)
        queue = deque()
        if i-1 >= 0 and j-1 >= 0:
            queue.append((i-1, j-1))
        visited = set()
        while queue:
            x, y = queue.popleft()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            new_g = (g[x+1][y] + g[x][y+1]) * A[x][y] % MOD
            if new_g != g[x][y]:
                g[x][y] = new_g
                if x-1 >= 0:
                    queue.append((x-1, y))
                if y-1 >= 0:
                    queue.append((x, y-1))

        # The answer is dp[H-1][W-1] (or equivalently g[0][0])
        out.append(str(dp[H-1][W-1] % MOD))

    print('\n'.join(out))

