from typing import List
from math import gcd

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        n = len(nums)
        parent = list(range(n))
        rank = [0] * n

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            rx, ry = find(x), find(y)
            if rx == ry:
                return
            if rank[rx] < rank[ry]:
                rx, ry = ry, rx
            parent[ry] = rx
            if rank[rx] == rank[ry]:
                rank[rx] += 1

        # Map each value to its index (values are unique)
        idx = {v: i for i, v in enumerate(nums)}

        # For each possible lcm value m <= threshold, connect all pairs
        # of array elements that both divide m.
        # For each m, gather indices of nums divisible by m... actually
        # we need nums[i] divides m and nums[j] divides m => lcm divides m <= threshold.
        # lcm(a,b) <= threshold iff there exists m = lcm(a,b) <= threshold with a|m, b|m.
        # So for each m <= threshold, all elements dividing m are pairwise connected.
        # Union them together (connect each to the first one found).

        # smallest[m] = index of some array element dividing m (first found)
        smallest = [-1] * (threshold + 1)

        for i, v in enumerate(nums):
            if v > threshold:
                continue
            # iterate over multiples of v
            for m in range(v, threshold + 1, v):
                if smallest[m] == -1:
                    smallest[m] = i
                else:
                    union(i, smallest[m])

        # Count distinct roots
        roots = set()
        for i in range(n):
            roots.add(find(i))
        return len(roots)
